from pathlib import Path
import os,json,hashlib
assert os.environ.get('MICRODUCK_BOUNDED_CAD')
import numpy as np,trimesh,manifold3d as mf
D=Path(__file__).resolve().parent;R=D.parents[3];report=json.loads((D/'assembly-check.json').read_text());c=json.loads((D/'candidate.json').read_text());assert report['passed'];assert report['candidateSha256']==hashlib.sha256((D/'candidate.json').read_bytes()).hexdigest()
