 out=D/(row['key']+'-print.stl');out.write_text(trimesh.exchange.stl.export_stl_ascii(m));r=trimesh.load(out,force='mesh');assert r.is_volume and np.max(np.abs(r.bounds-m.bounds))<1e-8
 parts.append({'key':row['key'],'color':'Black','quantity':1,'worldMesh':ref(p),'printMesh':ref(out),'worldToPrint':T.tolist(),'printBoundsMm':m.bounds.tolist(),'flatContactAreaMm2':area,'intendedBottom':'Existing continuous cage lower plane; no material shaved to create a bed face.','throughHoles':{'quantity':2,'diameterMm':2.8,'worldAxis':[0,0,1]},'nativeSlicePending':True})
