sourceContract=R/'head-redesign-20261008/curved-head/verify_mount_access.py';assert sourceContract.exists()
fragment={'status':'LOCAL_SPEAKER_MOUNT_GEOMETRY_PASSED','integrationReady':True,'wholeHeadAccepted':False,'manufacturingAccepted':False,'physicalFitVerified':False,'sourceManifest':c['sourceManifest'],'sourceSha256':c['sourceSha256'],'receipt':ref(D/'assembly-check.json'),'candidateReceipt':ref(D/'candidate.json'),'originalSpeakerUnchanged':True,'originalExteriorUnchanged':True,'replacementParts':[{'replaces':'current_cradle',**parts[0]['worldMesh'],'key':'speaker_cradle'},{'replaces':'REFERENCE current speaker_keeper',**parts[1]['worldMesh'],'key':'speaker_keeper'}],'capAddition':next(q for q in c['parts']if q['key']=='speaker_roof_posts'),'hardware':fasteners,'printParts':parts,'capNativeParameters':c['mounts'],'fastenerGeometrySource':ref(sourceContract),'assemblyOrder':[{'phase':'prepare','text':'Detach the cap. Complete speaker wiring before closing the cage. Keep controller/Pi boards out of the driver approach until these two screws are fitted.'},{'phase':'assemble','text':'Place the separate keeper against the two roof bosses, lower the speaker into that open seat from below, then fit the lower cradle. Neither retaining lip requires a snap-through motion.'},{'phase':'assemble','text':'Fit the two existing-specification M2.5 x 8 tapping screws from below through the 2.8 mm clearance holes. Nominal printed stack is 5.01 mm; pilot engagement is 2.99 mm with 0.31 mm bottom allowance.'},{'phase':'check','text':'Confirm the speaker remains captured at its perimeter without touching the grille or magnet. Check both screw heads seat flat. Then install the remaining cap-mounted electronics and close the complete cap group.'}],'coverage':{'independentStaticPairs':report['completedStaticPairs'],'allChecks':len(report['checks']),'failures':0,'capMotion':'Only changed speaker/cage/posts subset versus fixed mechanisms; controller/Pi/amp move with cap. Final complete head motion remains integration owner responsibility.','newOtherMounts':'This check binds custom-harness-package, not the subsequent controller/Pi mount additions. Cross-check those additions at integration.'},'sourceHashes':{str(D/x):sha(D/x)for x in ['build_candidate.py','check_candidate.py','finish_subset.py','initial-negative.json','head-envelope-negative.json','fixed-controller-closure-negative.json']}}
